    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] nums = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            nums[i] = (long) in.nval;
        }
        in.nextToken();
        int q = (int) in.nval;
        int[][] queries = new int[q][3];
        for (int j = 0; j < q; j++) {
            for (int c = 0; c < 3; c++) {
                in.nextToken();
                queries[j][c] = (int) in.nval;
            }
        }
        System.out.println(minK(nums, queries));
    }
}
